    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(20, 10) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 5 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, -5) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(bSketch, "rect1", { "firstCorner" : vector(10, -5) * millimeter, "secondCorner" : vector(30, 15) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "entities" : qSketchRegion(id + "bSketch"), "endBound" : BoundingType.BLIND, "depth" : 15 * millimeter });
    splitPart(context, id + "split1", { "targets" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "tool" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "b", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(10, 5, 2.5) * millimeter) });
}

// delete: delete one of two bodies
export function c067(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(bSketch, "rect1", { "firstCorner" : vector(20, 0) * millimeter, "secondCorner" : vector(30, 10) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "entities" : qSketchRegion(id + "bSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    deleteBodies(context, id + "delete1", { "entities" : qBodyType(qCreatedBy(id + "a", EntityType.BODY), BodyType.SOLID) });
}

// delete: delete every body a case made
export function c068(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(bSketch, "circle1", { "center" : vector(20, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "entities" : qSketchRegion(id + "bSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    deleteBodies(context, id + "delete1", { "entities" : qUnion([qBodyType(qCreatedBy(id + "a", EntityType.BODY), BodyType.SOLID), qBodyType(qCreatedBy(id + "b", EntityType.BODY), BodyType.SOLID)]) });
    return { "deleted" : true };
}

