// cpoint: point a quarter of the way along a slanted edge
export function c078(context is Context, id is Id)
{
    const line1 = newSketchOnPlane(context, id + "line1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0.894427, -0.447214, 0), vector(0.267261, 0.534522, 0.801784)) });
    skLineSegment(line1, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(37.416574, 0) * millimeter });
    skSolve(line1);
    cPoint(context, id + "point1", { "pointType" : PointType.EDGE_POINT, "entities" : qCreatedBy(id + "line1", EntityType.EDGE), "parameter" : 0.25 });
}

// variable: assign a length and read it back
export function c079(context is Context, id is Id)
{
    assignVariable(context, id + "variable1", { "name" : "width", "variableType" : VariableType.LENGTH, "lengthValue" : 42 * millimeter });
    return { "width" : getVariable(context, "width") / millimeter };
}

// variable: assign a number and an angle
export function c080(context is Context, id is Id)
{
    assignVariable(context, id + "variable1", { "name" : "count", "variableType" : VariableType.NUMBER, "numberValue" : 7 });
    assignVariable(context, id + "variable2", { "name" : "tilt", "variableType" : VariableType.ANGLE, "angleValue" : 15 * degree });
    return { "count" : getVariable(context, "count"), "tilt" : getVariable(context, "tilt") / degree };
}

