    assignVariable(context, id + "variable1", { "name" : "gap", "mode" : VariableMode.MEASURED, "measurementMode" : VariableMeasurementMode.DISTANCE, "entityCouple" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(20, 10, 5) * millimeter)]) });
