// variable: a variable drives a box
export function c083(context is Context, id is Id)
{
    assignVariable(context, id + "variable1", { "name" : "depth", "variableType" : VariableType.LENGTH, "lengthValue" : 13 * millimeter });
    const sketch1 = newSketchOnPlane(context, id + "sketch1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(sketch1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(sketch1);
    extrude(context, id + "extrude1", { "entities" : qSketchRegion(id + "sketch1"), "endBound" : BoundingType.BLIND, "depth" : getVariable(context, "depth") });
}
